def inspect_historical_decision(decision,outcome=None):
    payload=decision.get("payload") or decision;smc=payload.get("smc_contract") or {};setup=smc.get("setup") or {}
    trace=smc.get("target_trace") or setup.get("target_trace") or {}
    return {"information_available_then":{"replay_timestamp":payload.get("replay_time") or payload.get("analysis_candle_time"),"future_candles_visible":False,"candle_cutoff":payload.get("analysis_candle_time"),"confirmed_swings":smc.get("swings") or [],"external_structure":(smc.get("structure") or {}).get("external_structure"),"internal_structure":(smc.get("structure") or {}).get("internal_structure"),"active_liquidity_references":smc.get("liquidity") or [],"structural_targets":trace,"target_source_audit":smc.get("target_source_audit") or setup.get("target_source_audit") or {},"history_depth_audit":smc.get("history_depth_audit") or setup.get("history_depth_audit") or {},"sweep_evidence":setup.get("sweep"),"displacement_evidence":setup.get("displacement"),"bos":setup.get("bos"),"mss":setup.get("mss"),"entry_array":setup.get("entry_array"),"lifecycle_state":setup.get("state"),"first_blocking_gate":(smc.get("gate_funnel") or {}).get("first_blocking_gate"),"decision":payload.get("decision")},"observed_later":{"label":"Information unavailable to the strategy at decision time","paper_outcome":outcome,"target_lifecycle_events":(outcome or {}).get("target_lifecycle_events",[])}}
